/* Standalone review prototype. Never calls backend or stores credentials. */
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',back:'m15 5-7 7 7 7',shop:'M4 9h16l-1 11H5L4 9Zm4 0V7a4 4 0 0 1 8 0v2',lock:'M6 10h12v10H6V10Zm3 0V7a3 3 0 0 1 6 0v3m-3 4v2',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7',phone:'M7 3h10v18H7V3Zm4 15h2',box:'m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4m-9 4v10M7 5l10 4',food:'M5 3v7m3-7v7M3 3v7a3 3 0 0 0 6 0V3M6 13v8M18 3v18m0-18c-4 2-4 10 0 10',route:'M6 6h10a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8m-2-19a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',info:'M12 8v.1M12 11v6M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',wifi:'M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0m-9 4a4 4 0 0 1 6 0m-3 4h.01M3 3l18 18',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.shop}"/></svg>`;
const brand=()=>'<div class="brand"><img src="assets/karryam-logo.png" alt="Karryam"></div>';
const status=()=>'<div class="status" aria-hidden="true"><span>9:41</span><span class="island"></span><span class="status-icons"><svg viewBox="0 0 20 16"><path d="M1 12h3v4H1zm5-4h3v8H6zm5-4h3v12h-3zm5-4h3v16h-3z"/></svg><svg viewBox="0 0 20 16"><path d="M10 15 7 12a4 4 0 0 1 6 0zm-5-5L3 8a10 10 0 0 1 14 0l-2 2a7 7 0 0 0-10 0zM1 6 0 4a15 15 0 0 1 20 0l-1 2A13 13 0 0 0 1 6z"/></svg><span class="battery"></span></span></div>';
const home=()=>'<div class="home" aria-hidden="true"></div>';
const btn=(text,target,extra='')=>`<button type="${target?'button':'submit'}" class="primary ${extra}" ${target?`data-go="${target}"`:''}>${text}${icon('arrow')}</button>`;
const nav=(back='welcome',skip=false)=>`<div class="nav">${back?`<button type="button" class="back" data-go="${back}" aria-label="Go back">${icon('back')}</button>`:brand()}${back?brand():skip?'<button type="button" class="text-action" data-go="sign-in-phone">Skip</button>':''}</div>`;
const dots=i=>`<div class="steps" aria-label="Onboarding step ${i+1} of 3">${[0,1,2].map(n=>`<span class="${n===i?'active':''}"></span>`).join('')}</div>`;
const introFooter=(label,target)=>`<div class="footer">${btn(label,target)}<p class="quiet">Already part of Karryam? <button class="text-action" data-go="sign-in-phone">Sign in</button></p></div>`;
const badge=n=>`<div class="badge-icon">${icon(n)}</div>`;
const screen=(id,title,html,dark=false)=>({id,title,html,dark});
const signIn=email=>`${nav('welcome')}<div class="auth-body signin-body">${badge('shop')}<div class="eyebrow" style="color:var(--ink-teal);margin-bottom:12px">Your business, connected</div><h2>Welcome to<br>Karryam.</h2><p class="lead">Sign in to your vendor account.<br>We’ll send you a verification code.</p><div class="tabs" role="tablist" aria-label="Sign-in method"><button role="tab" aria-selected="${!email}" class="${!email?'selected':''}" data-go="sign-in-phone">Phone number</button><button role="tab" aria-selected="${email}" class="${email?'selected':''}" data-go="sign-in-email">Email address</button></div><form class="signin-form" id="signin-${email?'email':'phone'}" data-method="${email?'email':'phone'}"><label class="field-label" for="${email?'email':'phone'}">${email?'Email address':'Phone number'}</label><input class="field" id="${email?'email':'phone'}" name="${email?'email':'phone'}" type="${email?'email':'tel'}" autocomplete="${email?'email':'tel'}" placeholder="${email?'you@yourbusiness.com':'+234 801 234 5678'}" ${email?'':'inputmode="tel"'} required aria-describedby="${email?'email':'phone'}-helper"><p class="helper" id="${email?'email':'phone'}-helper">${email?'Use the email linked to your vendor access.':'Include your country code. Use the number linked to your vendor access.'}</p><div class="notice">${icon('shield')}<span>A secure code to sign in.<br>No password to remember.</span></div></form></div><div class="auth-footer"><button type="submit" class="primary" form="signin-${email?'email':'phone'}">Send verification code ${icon('arrow')}</button><p>Vendor access is managed by your business.<br>If you need access, contact your business owner.</p></div>`;
const code=(id,{email=false,error=false,expired=false,loading=false}={})=>`${nav(email?'sign-in-email':'sign-in-phone')}<div class="auth-body ${error?'error':''}">${badge(email?'mail':'lock')}<h2>${expired?'Your code<br>has expired.':'Check your<br>'+ (email?'email.':'messages.')}</h2><p>Enter the 6-digit code sent to <span class="masked" data-contact>${email?'a•••@yourbusiness.com':'+234 ••• ••• 5678'}</span></p><button type="button" class="edit-contact" data-go="${email?'sign-in-email':'sign-in-phone'}">Change ${email?'email address':'phone number'} ${icon('arrow')}</button><form class="code-form" data-email="${email}"><label class="field-label" for="otp-${id}" style="margin-top:18px">Verification code</label><div class="otp-group">${Array.from({length:6},()=>`<span class="otp-cell" aria-hidden="true">${error?'•':''}</span>`).join('')}<input class="otp-input" id="otp-${id}" name="otp" type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required aria-label="6-digit verification code" ${expired||loading?'disabled':''}></div>${error?`<div class="error-note" role="alert">${icon('info')}<span>That code is invalid or has expired. Check your latest code and try again.</span></div>`:expired?`<div class="error-note" role="alert">${icon('clock')}<span>Request a new code to continue signing in.</span></div>`:''}<div class="code-meta"><span>${expired?'Code expired':'Code expires in <strong data-expiry>04:59</strong>'}</span>${expired?'':`<button type="button" class="text-action" data-resend>Resend code</button>`}</div><div style="margin-top:32px">${expired?btn('Send a new code','code-phone'):loading?'<button type="button" class="primary loading-button" disabled><span class="spinner"></span>Verifying your code…</button>':'<button type="submit" class="primary verify-button" disabled>Verify and continue '+icon('arrow')+'</button>'}</div></form><div class="safe-note">${icon('lock')}Keep your sign-in code private.</div></div><div class="auth-footer"><p>Use the latest code sent to you.<br>You can paste it directly into the code field.</p></div>`;
const data=[
screen('splash','01 / Splash',`<div class="splash-main"><svg class="splash-route" viewBox="0 0 393 430" fill="none" aria-hidden="true"><path d="M-50 350C90 350 100 210 196 210S305 60 430 60" stroke="#00C2A8" stroke-width="1.5"/><circle cx="196" cy="210" r="6" fill="#00C2A8"/><circle cx="196" cy="210" r="15" stroke="#00C2A8" stroke-opacity=".5"/></svg><img class="big-logo" src="assets/karryam-logo.png" alt="Karryam"><span class="surface-label">FOR YOUR BUSINESS</span></div><div class="splash-footer"><div class="loader" aria-label="Starting Karryam"><i></i><i></i><i></i></div><p>MOVEMENT INTELLIGENCE<br>FOR A BRIGHTER TOMORROW</p><p style="margin-top:18px;letter-spacing:0;color:#A7B0BB">A CosmicForge Brand</p></div>`,true),
screen('welcome','02 / Onboarding · Your business',`${nav(null,true)}<div class="welcome-art"><img src="assets/vendor-welcome.png" alt="Nigerian business owner in a modern food and grocery shop"><span class="art-tag">${icon('shop')} Made for businesses like yours</span></div><div class="intro-copy">${dots(0)}<h2>Your business.<br><span class="accent">Brighter possibilities.</span></h2><p>Bring your food or shop business together with connected orders and fulfilment.</p></div>${introFooter('Explore Karryam','catalogue')}`,true),
screen('catalogue','03 / Onboarding · Food & Shop',`${nav(null,true)}<div class="catalogue-art"><div class="connection">${icon('route')}</div><div class="product-tile food"><img src="assets/food.png" alt="Freshly prepared meal"><span>${icon('food')} Food menus</span></div><div class="product-tile shop"><img src="assets/shop.png" alt="Groceries and retail essentials"><span>${icon('shop')} Shop products</span></div></div><div class="intro-copy">${dots(1)}<h2>What you sell.<br>Beautifully organised.</h2><p>Manage your food menus or shop catalogue, with prices and availability in one place.</p></div>${introFooter('Continue','fulfilment')}`),
screen('fulfilment','04 / Onboarding · Fulfilment',`${nav(null,true)}<div class="fulfilment-art"><svg class="route" viewBox="0 0 345 310" fill="none" aria-hidden="true"><path d="M50 45H250Q300 45 300 100V160Q300 200 250 200H95Q45 200 45 255H170" stroke="#00C2A8" stroke-width="2" stroke-dasharray="5 7"/><circle cx="50" cy="45" r="7" fill="#00C2A8"/><circle cx="170" cy="255" r="7" fill="#00C2A8"/></svg><div class="node-card one"><span class="node-icon">${icon('shop')}</span><span class="node-label">Receive orders<small>See what needs your attention</small></span></div><div class="node-card two"><span class="node-icon">${icon('box')}</span><span class="node-label">Prepare with care<small>Keep progress up to date</small></span></div><div class="node-card three"><span class="node-icon">${icon('shield')}</span><span class="node-label">Confirm pickup<small>Follow secure handover</small></span></div></div><div class="intro-copy">${dots(2)}<h2>From your business.<br><span class="accent">To their doorstep.</span></h2><p>Follow each order through preparation and the fulfilment steps available to your business.</p></div>${introFooter('Sign in to your business','sign-in-phone')}`,true),
screen('sign-in-phone','05 / Sign in · Phone',signIn(false)),
screen('sign-in-email','06 / Sign in · Email',signIn(true)),
screen('code-phone','07 / Verify · Phone',code('phone')),
screen('code-email','08 / Verify · Email',code('email',{email:true})),
screen('vendor-choice','09 / Choose vendor',`${nav('code-phone')}<div class="auth-body">${badge('shop')}<h2>Choose your<br>vendor account.</h2><p>Your sign-in is linked to more than one vendor. Select the account to continue.</p><div class="vendor-list" role="radiogroup" aria-label="Available vendor accounts">${['8ab421d4-7e6c-4bce-9d3e-05f18e21a064','c178b37a-36f2-4a41-8d20-6d437c24bf72'].map((v,i)=>`<button type="button" class="vendor-row ${i===0?'selected':''}" role="radio" aria-checked="${i===0}" data-vendor="${v}"><span class="node-icon">${icon('shop')}</span><span class="vendor-info"><strong>Vendor ID</strong><small>${v}</small></span><span class="radio"></span></button>`).join('')}</div><div class="notice">${icon('lock')}<span>Continue with the same sign-in code.<br>You do not need to request another one.</span></div></div><div class="auth-footer">${btn('Continue','signed-in')}</div>`),
screen('signed-in','10 / Authentication complete',`${nav(null)}<div class="center-state"><div class="success-art"><span class="inner">${icon('check')}</span></div><div class="state-kicker">You’re connected</div><h2>Welcome back.</h2><p>You’re signed in to your vendor account.</p></div><div class="state-footer"><p>Your business session is ready.</p></div>`),
screen('invalid-code','11 / Incorrect code',code('invalid',{error:true})),
screen('expired-code','12 / Expired code',code('expired',{expired:true})),
screen('verifying','13 / Verifying',code('verifying',{loading:true})),
screen('network-error','14 / Connection recovery',`${nav('sign-in-phone')}<div class="center-state"><div class="state-art">${icon('wifi')}</div><h2>Let’s reconnect.</h2><p>We couldn’t complete your sign-in request. Check your connection and try again.</p></div><div class="auth-footer">${btn('Try again','sign-in-phone')}<p>Your details stay on this screen while you retry.</p></div>`),
screen('access-unavailable','15 / Access unavailable',`${nav('sign-in-phone')}<div class="center-state"><div class="state-art">${icon('user')}</div><h2>Vendor access<br>is unavailable.</h2><p>You do not have active staff access to a vendor business. Contact your business owner.</p></div><div class="auth-footer">${btn('Use another account','sign-in-phone')}</div>`),
screen('access-suspended','16 / Access suspended',`${nav('sign-in-phone')}<div class="center-state"><div class="state-art">${icon('lock')}</div><h2>Your access<br>has been suspended.</h2><p>Contact your business owner to check your vendor access.</p></div><div class="auth-footer">${btn('Back to sign in','sign-in-phone')}</div>`)
];
const query=new URLSearchParams(location.search), initial=query.get('screen');
let mode=query.get('mode')||'gallery';let current=initial||'splash';let splashTimer;const draft={phone:'',email:'',otp:'',method:'phone',vendor:null};
function render(){document.body.classList.toggle('single-mode',mode!=='gallery');document.body.classList.toggle('prototype-mode',mode==='prototype');document.body.classList.toggle('capture-mode',mode==='phone');document.getElementById('board').innerHTML=data.map(s=>`<section class="screen-wrap" id="${s.id}" ${mode!=='gallery'&&s.id!==current?'hidden':''}><div class="screen-caption"><span>${s.title}</span><a href="?mode=prototype&screen=${s.id}">Open ↗</a></div><article class="phone ${s.dark?'dark':''}" aria-label="${s.title}">${status()}${s.html}${home()}</article></section>`).join('');bind();clearTimeout(splashTimer);if(mode==='prototype'&&current==='splash')splashTimer=setTimeout(()=>go('welcome'),1200);}
function go(id){if(!data.some(s=>s.id===id))return;if(mode==='gallery')mode='prototype';current=id;query.set('mode',mode);query.set('screen',id);history.replaceState(null,'','?'+query);render();if(mode==='prototype')document.querySelector('#'+id+' .phone')?.scrollIntoView({block:'start',behavior:'instant'});}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>go(b.dataset.preview));document.querySelectorAll('.signin-form').forEach(f=>{const input=f.querySelector('input');input.value=draft[f.dataset.method];input.oninput=()=>{draft[f.dataset.method]=input.value;input.setCustomValidity('')};f.onsubmit=e=>{e.preventDefault();if(f.dataset.method==='phone'&&!/^\+[1-9]\d{6,14}$/.test(input.value.replace(/[\s()-]/g,''))){input.setCustomValidity('Enter your phone number with its country code, such as +234…');input.reportValidity();return}if(!f.reportValidity())return;draft.method=f.dataset.method;draft.otp='';go(draft.method==='email'?'code-email':'code-phone')}});document.querySelectorAll('.code-form').forEach(f=>{const input=f.querySelector('input'),cells=f.querySelectorAll('.otp-cell'),submit=f.querySelector('.verify-button');const contact=f.closest('.auth-body').querySelector('[data-contact]');const method=f.dataset.email==='true'?'email':'phone';if(draft[method])contact.textContent=mask(draft[method],method);if(current==='verifying')input.value=draft.otp;function update(){input.value=input.value.replace(/[^0-9]/g,'').slice(0,6);cells.forEach((c,i)=>c.textContent=input.value[i]||'');if(submit)submit.disabled=input.value.length!==6}input.oninput=update;if(current==='verifying')update();f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;draft.otp=input.value;go('verifying');setTimeout(()=>{if(current==='verifying')go('vendor-choice')},900)}});document.querySelectorAll('[data-resend]').forEach(b=>b.onclick=()=>{draft.otp='';go(draft.method==='email'?'code-email':'code-phone');document.getElementById('demo-status').textContent='Preview: a new code would be requested from the backend.'});document.querySelectorAll('[data-vendor]').forEach(b=>b.onclick=()=>{draft.vendor=b.dataset.vendor;b.parentElement.querySelectorAll('[data-vendor]').forEach(r=>{r.classList.toggle('selected',r===b);r.setAttribute('aria-checked',r===b?'true':'false')})});if(current==='vendor-choice'&&!draft.vendor)draft.vendor='8ab421d4-7e6c-4bce-9d3e-05f18e21a064';}
function mask(value,method){if(method==='email'){const [name,domain]=value.split('@');return (name?.slice(0,1)||'')+'•••@'+(domain||'')}return value.slice(0,4)+' ••• ••• '+value.replace(/\D/g,'').slice(-4)}
render();
